import{_ as o,l as n,o as a,c as d,v as e,p as m,x as r,d as l,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"二次变差","description":"","frontmatter":{"title":"二次变差","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/quadratic-variation.md","filePath":"quant/quadratic-variation.md","lastUpdated":1789023840000}'),_={name:"quant/quadratic-variation.md"};function p(E,t,c,u,B,W){const i=n("Mermaid");return a(),d("div",null,[t[1]||(t[1]=e('<h1 id="二次变差" tabindex="-1">二次变差 <a class="header-anchor" href="#二次变差" aria-label="Permalink to &quot;二次变差&quot;">​</a></h1><div class="epigraph"><p>分区细化后，布朗增量的平方和几乎必然收敛到日历时间 $t$；一阶变差却发散。乘法规则因此是 $(\\mathrm d W)^2=\\mathrm d t$，不是零。</p><footer>—— 据 Karatzas and Shreve, Brownian Motion and Stochastic Calculus, 1991, §1.5；Shreve, Stochastic Calculus for Finance II, 2004, 第 3 章整理</footer></div><p>上一课<a href="/quant/brownian-motion-paths">布朗运动与路径性质</a>钉死了连续、不可微、\\(\\mathrm{Var}(W_t)=t\\)。缺口不是再列一遍公理，而是：在这种路径上，经典链式法则丢掉的二阶项究竟收敛到什么。没有二次变差，伊藤引理没有修正项，SDE 只是记号。本课只补这一块收敛。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>光滑函数满足 \\(|\\Delta x|^2=o(|\\Delta x|)\\)，泰勒展开可以丢掉二阶。布朗路径太粗：一阶变差 \\(\\sum_i|W_{t_{i+1}}-W_{t_i}|\\) 随网格加密趋于无穷，Riemann–Stieltjes 积分 \\(\\int H\\,\\mathrm d W\\) 不能沿路径当普通 Stieltjes 来定义。同时，平方和 \\(\\sum_i(W_{t_{i+1}}-W_{t_i})^2\\) 并不发散——它收敛到一个确定的有限极限。缺口是把这个极限命名，并写成后课要用的乘法表。</p><h3 id="二次变差不是方差的另一写法" tabindex="-1">二次变差不是方差的另一写法 <a class="header-anchor" href="#二次变差不是方差的另一写法" aria-label="Permalink to &quot;二次变差不是方差的另一写法&quot;">​</a></h3><p>\\(\\mathrm{Var}(W_t)=t\\) 是分布的二阶矩，对固定 \\(t\\) 取期望。二次变差 \\([W]_t\\) 是<strong>路径上的</strong>平方增量极限，几乎必然等于 \\(t\\)。一个是 \\(\\mathbb E[W_t^2]\\)，一个是沿单条路径累加 \\((\\Delta W)^2\\)。Levy 刻画把两者焊在一起：连续局部鞅若二次变差为 \\(t\\)，则是布朗运动。本课先把路径极限钉死，不把刻画定理证一遍。</p><p><span class="marginnote">实现波动率是二次变差的离散估计，属于高频计量，不是本课对象。这里只需要 \\([W]_t=t\\) 作为伊藤乘法表的来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取分区 \\(0=t_0\\lt \\cdots\\lt t_n=t\\)，令 \\(Q_\\pi=\\sum_{i=0}^{n-1}(W_{t_{i+1}}-W_{t_i})^2\\)。网格步长 \\(\\|\\pi\\|\\to 0\\) 时，\\(Q_\\pi\\to t\\) 依概率（沿合适的细分序列则几乎必然）。定义 \\([W]_t=t\\)。交叉变差 \\([W,t]=0\\)、\\([t,t]=0\\)。形式乘法表：</p> \\[\\mathrm d W\\cdot\\mathrm d W=\\mathrm d t,\\qquad \\mathrm d W\\cdot\\mathrm d t=0,\\qquad \\mathrm d t\\cdot\\mathrm d t=0. \\]<p>对半鞅 \\(X_t=X_0+\\int\\mu+\\int\\sigma\\,\\mathrm d W\\)，有 \\([X]_t=\\int_0^t\\sigma_s^2\\,\\mathrm d s\\)（连续情形）。后课 GBM 的 \\([S]_t=\\int\\sigma^2 S^2\\,\\mathrm d s\\) 直接套这条。</p>',12)),(a(),m(h,null,{default:r(()=>[s(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20PATH%5B%22%E5%B8%83%E6%9C%97%E8%B7%AF%E5%BE%84%E4%B8%8D%E5%8F%AF%E5%BE%AE%22%5D%20--%3E%20FV%5B%22%E4%B8%80%E9%98%B6%E5%8F%98%E5%B7%AE%E6%97%A0%E7%A9%B7%22%5D%0A%20%20PATH%20--%3E%20QV%5B%22%E5%B9%B3%E6%96%B9%E5%92%8C%E6%94%B6%E6%95%9B%E5%88%B0%20t%22%5D%0A%20%20QV%20--%3E%20RULE%5B%22%E4%B9%98%E6%B3%95%E8%A1%A8%20dW%20dW%20%E7%AD%89%E4%BA%8E%20dt%22%5D%0A%20%20RULE%20--%3E%20ITO%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E4%BC%8A%E8%97%A4%E5%BC%95%E7%90%86%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>独立高斯增量使 \\(Q_\\pi\\) 的期望恰好是 \\(t\\)，方差随 \\(\\|\\pi\\|\\to 0\\) 消失，所以极限是确定性过程 \\(t\\)，不是新的随机过程。这解释了「噪声的平方变成时间」：随机性在一阶，二次项平均掉只剩日历钟。伊藤积分把被积过程放在左端点（非预期），正是为了让 \\(\\int H\\,\\mathrm d W\\) 对二次变差的收敛保持鞅性质；那是后课积分方程的事，本课只提供 \\([W]\\)。</p><p>有界变差的有限变差过程与 \\(W\\) 的交叉变差几乎必然为零。因此漂移项不贡献二次变差，只有扩散系数进入 \\([X]\\)。定价里「谁贡献凸性、谁只贡献漂移」从这里分开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义伊藤积分，不证 Itô 等距，不讨论 p-变差。分数布朗运动的二次变差可以是零或无穷，主干不用。带跳过程的二次变差会多一项跳幅平方和，留给<a href="/quant/jump-process-intuition">跳过程直觉</a>。后课默认：\\([W]_t=t\\)，写泰勒展开时 \\((\\mathrm d W)^2\\) 保留为 \\(\\mathrm d t\\)。下一课<a href="/quant/ito-lemma">伊藤引理</a>把这条乘法表装进链式法则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>布朗二次变差 \\([W]_t=t\\)；一阶变差发散。</li><li>形式规则 \\(\\mathrm d W\\cdot\\mathrm d W=\\mathrm d t\\)，其余交叉为零。</li><li>二次变差是路径极限，不是 \\(\\mathrm{Var}(W_t)\\) 的别名。</li><li>连续半鞅的 \\([X]\\) 只由扩散系数决定。</li><li>出处：Karatzas–Shreve §1.5；Shreve, SDE II 第 3 章。</li></ul>',7))])}const f=o(_,[["render",p]]);export{A as __pageData,f as default};
